from django.conf import settings
from django.db import migrations, models

#: The statuses the redaction compute may be queued from
#: (``yolo.APPLY_STATUSES``), inlined so the migration does not import
#: the app.
_APPLY_STATUSES = (
    "page_completeness_review_done",
    "ready_for_redaction_review",
)


def blank_redaction_ledgers(apps, schema_editor):
    """Make every scan in review 2 owe a redaction compute.

    :param apps: The historical app registry.
    :param schema_editor: Unused.
    :return: None.
    """
    ExternalJob = apps.get_model("scanning", "ExternalJob")
    heads = ExternalJob.objects.filter(
        stage="detect",
        engine="blackletter",
        provider="runpod",
        shard_index=0,
        apply_run__isnull=True,
        scan__status__in=_APPLY_STATUSES,
        provider_meta__apply__apply_run__isnull=False,
    )
    blanked = 0
    for head in heads:
        meta = dict(head.provider_meta or {})
        state = dict(meta.get("apply") or {})
        if state.get("apply_run") is None:
            continue
        state.pop("apply_run", None)
        meta["apply"] = state
        head.provider_meta = meta
        head.save(update_fields=["provider_meta"])
        blanked += 1
    Scan = apps.get_model("scanning", "Scan")
    closed = Scan.objects.filter(status="redaction_review_done").count()
    logging.getLogger(__name__).info(
        "redaction ledgers blanked: %d; closed reviews left without rows: %d",
        blanked,
        closed,
    )


